```minizinc
include "globals.mzn";

int: n = 4;
set of int: N = 1..n;
set of int: Values = 1..n*n;
int: magic_sum = n*(n*n + 1) div 2;

array[N,N] of var Values: square;

constraint all_different([square[i,j] | i in N, j in N]);

% Row sums
constraint forall(i in N) (
    sum([square[i,j] | j in N]) = magic_sum
);

% Column sums
constraint forall(j in N) (
    sum([square[i,j] | i in N]) = magic_sum
);

% Diagonal sums
constraint sum([square[i,i] | i in N]) = magic_sum;
constraint sum([square[i,n+1-i] | i in N]) = magic_sum;

% Symmetry breaking (to reduce search space)
constraint square[1,1] < square[1,n];
constraint square[1,1] < square[n,1];
constraint square[1,1] < square[n,n];
constraint square[1,n] < square[n,1];

solve satisfy;

output [
    "{\n",
    "\"" ++ "square" ++ "\": [\n",
    join(",\n", [
        "[" ++ join(", ", [show(square[i,j]) | j in N]) ++ "]" | i in N
    ]),
    "\n]\n}"
];
```

