```minizinc
include "globals.mzn";

% Input data
int: n = 4; % number of items
array[1..n] of int: widths = [3, 4, 2, 1];
array[1..n] of int: heights = [2, 3, 1, 4];

% Decision variables
var int: total_x;
var int: total_y;
array[1..n] of var int: pos_x;
array[1..n] of var int: pos_y;

% Constraints
constraint forall(i in 1..n) (pos_x[i] >= 0 /\ pos_x[i] + widths[i] <= total_x);
constraint forall(i in 1..n) (pos_y[i] >= 0 /\ pos_y[i] + heights[i] <= total_y);

% No overlap constraint
constraint forall(i,j in 1..n where i < j) (
    pos_x[i] + widths[i] <= pos_x[j] \/
    pos_x[j] + widths[j] <= pos_x[i] \/
    pos_y[i] + heights[i] <= pos_y[j] \/
    pos_y[j] + heights[j] <= pos_y[i]
);

% Objective: minimize area
var int: area = total_x * total_y;
solve minimize area;

% Output
output [
    "{",
    join(",", [
        "\"" ++ "positions" ++ "\": [" ++ 
            join(",", ["{\"x\": " ++ show(pos_x[i]) ++ ", \"y\": " ++ show(pos_y[i]) ++ "}" | i in 1..n]) ++ "]",
        "\"" ++ "total_x" ++ "\": " ++ show(total_x),
        "\"" ++ "total_y" ++ "\": " ++ show(total_y)
    ]),
    "}"
];
```

