include "globals.mzn";

int: stages = 8;  % Number of stages/steps in the solution

% Decision variables: position at each stage (0 = starting shore, 1 = destination shore)
array[1..stages] of var 0..1: wolf_pos;
array[1..stages] of var 0..1: goat_pos;
array[1..stages] of var 0..1: cabbage_pos;
array[1..stages] of var 0..1: boat_pos;

% Initial state: all on starting shore
constraint wolf_pos[1] == 0;
constraint goat_pos[1] == 0;
constraint cabbage_pos[1] == 0;
constraint boat_pos[1] == 0;

% Final state: all on destination shore
constraint wolf_pos[stages] == 1;
constraint goat_pos[stages] == 1;
constraint cabbage_pos[stages] == 1;
constraint boat_pos[stages] == 1;

% Boat moves each stage (changes position)
constraint forall(s in 1..stages-1) (boat_pos[s+1] != boat_pos[s]);

% Farmer is always with the boat (implied by problem description)
% Only one item can be moved at a time (or nothing)
constraint forall(s in 1..stages-1) (
    % Count how many items change position
    sum([wolf_pos[s+1] != wolf_pos[s], 
         goat_pos[s+1] != goat_pos[s], 
         cabbage_pos[s+1] != cabbage_pos[s]]) <= 1
);

% Safety constraints: wolf and goat cannot be left alone, goat and cabbage cannot be left alone
constraint forall(s in 1..stages) (
    % Wolf and goat together without farmer
    (wolf_pos[s] == goat_pos[s] /\ boat_pos[s] != wolf_pos[s]) -> false
    /\
    % Goat and cabbage together without farmer
    (goat_pos[s] == cabbage_pos[s] /\ boat_pos[s] != goat_pos[s]) -> false
);

% Movement constraints: when boat moves, only items on the same side as boat can move
constraint forall(s in 1..stages-1) (
    % If wolf moves, it must be on same side as boat before moving
    (wolf_pos[s+1] != wolf_pos[s]) -> (wolf_pos[s] == boat_pos[s])
    /\
    % If goat moves, it must be on same side as boat before moving
    (goat_pos[s+1] != goat_pos[s]) -> (goat_pos[s] == boat_pos[s])
    /\
    % If cabbage moves, it must be on same side as boat before moving
    (cabbage_pos[s+1] != cabbage_pos[s]) -> (cabbage_pos[s] == boat_pos[s])
);

solve satisfy;

output [
    "{",
    join(",", [
        "\"" ++ "wolf_pos" ++ "\": [" ++ join(",", [show(wolf_pos[s]) | s in 1..stages]) ++ "]",
        "\"" ++ "goat_pos" ++ "\": [" ++ join(",", [show(goat_pos[s]) | s in 1..stages]) ++ "]",
        "\"" ++ "cabbage_pos" ++ "\": [" ++ join(",", [show(cabbage_pos[s]) | s in 1..stages]) ++ "]",
        "\"" ++ "boat_pos" ++ "\": [" ++ join(",", [show(boat_pos[s]) | s in 1..stages]) ++ "]"
    ]),
    "}"
];
```

This model:
1. Defines position variables for each item and the boat at each stage
2. Sets initial and final conditions
3. Ensures the boat moves each stage
4. Limits movement to one item at a time
5. Prevents unsafe combinations (wolf+goat or goat+cabbage without farmer)
6. Ensures only items on the same side as the boat can be moved

The output shows the positions (0 or 1) of each item and the boat at each stage. A typical solution would show the sequence of moves where the farmer transports items while avoiding the dangerous combinations.

Note that with 8 stages, this should find the classic 7-move solution (plus the initial state). The model is flexible enough to find solutions with more stages if needed.

