% The Englishman lives in the red house
constraint forall(h in HOUSE)(nations[h] == england <-> colors[h] == red);

% The snails are owned by the sculptor
constraint forall(h in HOUSE)(pets[h] == snails <-> jobs[h] == sculptor);

% The green house is immediately to the left of the red one
constraint exists(h in 1..n-1)(colors[h] == green /\ colors[h+1] == red);

% The Norwegian lives on the right of the blue house
constraint exists(h1 in HOUSE, h2 in HOUSE where h1 < h2)
    (colors[h1] == blue /\ nations[h2] == norway);

