constraint forall(h in HOUSE)(jobs[h] == doctor <-> drinks[h] == milk);

% The diplomat is Japanese
constraint forall(h in HOUSE)(jobs[h] == diplomat <-> nations[h] == japan);

% The Norwegian owns the zebra
constraint forall(h in HOUSE)(nations[h] == norway <-> pets[h] == zebra);

% The green house is next to the white one
constraint exists(h in 1..n-1)(
    (colors[h] == green /\ colors[h+1] == white) \/
    (colors[h] == white /\ colors[h+1] == green)
);

% The horse is owned by the neighbor of the diplomat
constraint exists(h1 in HOUSE, h2 in HOUSE)(
    (abs(h1-h2) == 1) /\ 
    (pets[h1] == horse /\ jobs[h2] == diplomat)
);

% The Italian either lives in the red, white or green house
constraint forall(h in HOUSE)(
    nations[h] == italy -> (colors[h] == red \/ colors[h] == white \/ colors[h] == green)
);

solve satisfy;

output [
