    "\"colors\": [" ++ join(", ", [show(colors[h]) | h in HOUSE]) ++ "],\n",
    "\"nations\": [" ++ join(", ", [show(nations[h]) | h in HOUSE]) ++ "],\n",
    "\"jobs\": [" ++ join(", ", [show(jobs[h]) | h in HOUSE]) ++ "],\n",
    "\"pets\": [" ++ join(", ", [show(pets[h]) | h in HOUSE]) ++ "],\n",
    "\"drinks\": [" ++ join(", ", [show(drinks[h]) | h in HOUSE]) ++ "]",
    "}"
];
