array[1..n_containers] of var 0..deck_width: left;
array[1..n_containers] of var 0..deck_length: bottom;
array[1..n_containers] of var 0..deck_width: right;
array[1..n_containers] of var 0..deck_length: top;

% Constraints
constraint forall(i in 1..n_containers) (
    right[i] = left[i] + width[i] /\
    top[i] = bottom[i] + length[i]
);

% Containers must fit within deck
constraint forall(i in 1..n_containers) (
    right[i] <= deck_width /\
    top[i] <= deck_length
);

% No overlapping containers
constraint forall(i, j in 1..n_containers where i < j) (
    left[i] >= right[j] \/ left[j] >= right[i] \/
    bottom[i] >= top[j] \/ bottom[j] >= top[i]
);

% Loading sequence constraints (each container must touch north and west)
% First container must be in SE corner
constraint left[1] = 0 /\ bottom[1] = 0;

% Subsequent containers must touch north and west of existing containers or deck
constraint forall(i in 2..n_containers) (
    (exists(j in 1..i-1)(top[j] = bottom[i] \/ bottom[i] = 0)) /\
    (exists(j in 1..i-1)(right[j] = left[i] \/ left[i] = 0))
);

