set of int: PERIODS = 1..n_periods;

% Constraints

% 1. A boat is either a host or a guest (if not host, it visits someone each period)
constraint forall(b in BOATS) (
    is_host[b] == (forall(p in PERIODS)(visits[b,p] == 0))
);

% 2. Capacity constraints for each host in each period
constraint forall(h in BOATS where is_host[h]) (
    forall(p in PERIODS) (
        sum(g in BOATS where visits[g,p] == h)(crew_size[g]) + crew_size[h] <= capacity[h]
    )
);

% 3. A guest boat cannot revisit a host
constraint forall(g in BOATS where not is_host[g]) (
    alldifferent([visits[g,p] | p in PERIODS where visits[g,p] != 0])
);

% 4. Guest crews cannot meet more than once
constraint forall(g1, g2 in BOATS where g1 < g2 and not is_host[g1] and not is_host[g2]) (
    sum(p in PERIODS)(visits[g1,p] != 0 /\ visits[g2,p] != 0 /\ visits[g1,p] == visits[g2,p]) <= 1
);

% 5. Minimize the number of host boats
