constraint sum([dice[2,f1] > dice[5,f2] | f1 in 1..n_faces, f2 in 1..n_faces]) > n_faces*n_faces/2;

% Scissors (3) beats Paper (2) and Lizard (4)
constraint sum([dice[3,f1] > dice[2,f2] | f1 in 1..n_faces, f2 in 1..n_faces]) > n_faces*n_faces/2;
constraint sum([dice[3,f1] > dice[4,f2] | f1 in 1..n_faces, f2 in 1..n_faces]) > n_faces*n_faces/2;

% Lizard (4) beats Paper (2) and Spock (5)
constraint sum([dice[4,f1] > dice[2,f2] | f1 in 1..n_faces, f2 in 1..n_faces]) > n_faces*n_faces/2;
constraint sum([dice[4,f1] > dice[5,f2] | f1 in 1..n_faces, f2 in 1..n_faces]) > n_faces*n_faces/2;

% Spock (5) beats Rock (1) and Scissors (3)
constraint sum([dice[5,f1] > dice[1,f2] | f1 in 1..n_faces, f2 in 1..n_faces]) > n_faces*n_faces/2;
constraint sum([dice[5,f1] > dice[3,f2] | f1 in 1..n_faces, f2 in 1..n_faces]) > n_faces*n_faces/2;

